using Microsoft.EntityFrameworkCore.Metadata;

namespace Microsoft.EntityFrameworkCore.Metadata;

/// <summary>How SQLite generates a property's value on insert (Microsoft's <c>SqliteValueGenerationStrategy</c>).</summary>
public enum SqliteValueGenerationStrategy
{
    /// <summary>No strategy: the application supplies the value (or the key is not generated by the database).</summary>
    None,

    /// <summary>An integer key is AUTOINCREMENT, so the database numbers each new row.</summary>
    Autoincrement
}
